        ["competition.put_slots"] = new("competition.put_slots", "INSERT INTO app.competition_slots(competition_id,match_id,slot,entrant_id,from_match,from_place) SELECT $1,s.match_id,s.slot,s.entrant_id,s.from_match,s.from_place FROM unnest($2::text[],$3::int2[],$4::uuid[],$5::text[],$6::int2[]) AS s(match_id,slot,entrant_id,from_match,from_place)", ["uuid", "text[]", "int2[]", "uuid[]", "text[]", "int2[]"]),
        ["competition.record"] = new("competition.record", "SELECT s.entrant_id,count(*) FILTER (WHERE s.place=1),count(*) FILTER (WHERE s.place>1) FROM app.competition_slots s JOIN app.competition_matches m ON m.competition_id=s.competition_id AND m.match_id=s.match_id JOIN app.competition_entrants e ON e.competition_id=s.competition_id AND e.entrant_id=s.entrant_id WHERE s.competition_id=$1 AND m.state='final' GROUP BY s.entrant_id,e.seed ORDER BY 2 DESC,3,e.seed", ["uuid"]),
        ["competition.reformat"] = new("competition.reformat", "UPDATE app.competitions SET format=$2 WHERE competition_id=$1 AND status='registration'", ["uuid", "text"]),
        ["competition.register"] = new("competition.register", "INSERT INTO app.competition_entrants(competition_id,entrant_id,name) SELECT c.competition_id,$2,$3 FROM app.competitions c WHERE c.competition_id=$1 AND c.status='registration' AND (SELECT count(*) FROM app.competition_entrants e WHERE e.competition_id=c.competition_id)<$4 ON CONFLICT DO NOTHING", ["uuid", "uuid", "text", "int4"]),
        ["competition.register_many"] = new("competition.register_many", "INSERT INTO app.competition_entrants(competition_id,entrant_id,name,created_at) SELECT c.competition_id,n.entrant_id,n.name,clock_timestamp()+n.ord*interval '1 microsecond' FROM app.competitions c,LATERAL(SELECT u.entrant_id,u.name,row_number() OVER (ORDER BY u.ord) AS ord FROM unnest($3::uuid[],$4::text[]) WITH ORDINALITY u(entrant_id,name,ord) WHERE NOT EXISTS(SELECT 1 FROM app.competition_entrants e WHERE e.competition_id=c.competition_id AND lower(e.name)=lower(u.name))) n WHERE c.competition_id=$1 AND c.tenant=$2 AND c.status='registration' AND n.ord<=$5-(SELECT count(*) FROM app.competition_entrants e WHERE e.competition_id=c.competition_id) ON CONFLICT DO NOTHING", ["uuid", "text", "uuid[]", "text[]", "int4"]),
        ["competition.seed"] = new("competition.seed", "UPDATE app.competition_entrants e SET seed=s.n::int FROM unnest($2::uuid[]) WITH ORDINALITY s(entrant_id,n) WHERE e.competition_id=$1 AND e.entrant_id=s.entrant_id", ["uuid", "uuid[]"]),
        ["competition.session_cover"] = new("competition.session_cover", "UPDATE app.competition_sessions SET covered_until=now()+make_interval(hours=>$2) WHERE session_id=$1", ["uuid", "int4"]),
        ["competition.session_create"] = new("competition.session_create", "INSERT INTO app.competition_sessions(session_id,tenant,title) VALUES($1,$2,$3)", ["uuid", "text", "text"]),
        ["competition.session_join"] = new("competition.session_join", "INSERT INTO app.competition_session_events(competition_id,session_id) SELECT c.competition_id,s.session_id FROM app.competitions c,app.competition_sessions s WHERE c.competition_id=$1 AND s.session_id=$2 AND c.tenant=$3 AND s.tenant=$3", ["uuid", "uuid", "text"]),
        ["competition.session_of"] = new("competition.session_of", "SELECT s.session_id,s.title,COALESCE(s.covered_until>now(),false) FROM app.competition_session_events m JOIN app.competition_sessions s ON s.session_id=m.session_id WHERE m.competition_id=$1 FOR UPDATE OF s", ["uuid"]),
        ["competition.session_title"] = new("competition.session_title", "SELECT s.session_id,s.title,COALESCE(s.covered_until>now(),false) FROM app.competition_session_events m JOIN app.competition_sessions s ON s.session_id=m.session_id WHERE m.competition_id=$1", ["uuid"]),
        ["competition.sessions"] = new("competition.sessions", "SELECT session_id,title,created_at,covered_until FROM app.competition_sessions WHERE tenant=$1 ORDER BY created_at DESC LIMIT 200", ["text"]),
        ["competition.start"] = new("competition.start", "UPDATE app.competitions SET status='running',started_at=now() WHERE competition_id=$1 AND status='registration'", ["uuid"]),
        ["competition.withdraw"] = new("competition.withdraw", "DELETE FROM app.competition_entrants e USING app.competitions c WHERE e.competition_id=$1 AND e.entrant_id=$2 AND c.competition_id=e.competition_id AND c.tenant=$3 AND c.status='registration'", ["uuid", "uuid", "text"]),
        ["conversation.resolve_refs_with_labels"] = new("conversation.resolve_refs_with_labels", "SELECT ordinal, id, label, present FROM public.laplace_resolve_refs($1,$2)", ["bytea[]", "text[]"]),
        ["display.labels"] = new("display.labels", "SELECT encode(d.id, 'hex'), d.label, d.tier FROM (SELECT public.blake3_send(lp_l.entity) AS id, lp_l.content AS label, coalesce(lp_e.tier, CASE WHEN public.laplace_codepoint(lp_l.entity) >= 0 THEN 0::smallint END) AS tier FROM public.laplace_labels(array_remove(($1)::bytea[], NULL)::public.blake3[]) lp_l LEFT JOIN public.laplace_entities(array_remove(($1)::bytea[], NULL)::public.blake3[]) lp_e ON lp_e.ordinal = lp_l.i) d", ["bytea[]"]),
        ["entity.facets"] = new("entity.facets", "WITH ids AS MATERIALIZED (SELECT DISTINCT u.id, public.blake3_from_bytea(u.id) AS key FROM unnest($1::bytea[]) u(id) WHERE u.id IS NOT NULL), native AS MATERIALIZED (SELECT e.id, e.tier FROM public.laplace_entities(ARRAY(SELECT key FROM ids)) e) SELECT i.id, coalesce(e.tier, 0)::smallint, NULL::bytea FROM ids i LEFT JOIN native e ON e.id = i.key WHERE e.tier IS NOT NULL OR public.laplace_codepoint(i.key) >= 0 ORDER BY i.id", ["bytea[]"]),
        ["identity.account"] = new("identity.account", "SELECT u.user_id,m.tenant_id,m.role,i.provider,u.email,u.display_name,u.avatar_url FROM app.external_identities i JOIN app.users u ON u.user_id=i.user_id JOIN app.tenant_memberships m ON m.user_id=u.user_id JOIN app.tenants t ON t.tenant_id=m.tenant_id WHERE i.provider=$1 AND i.issuer=$2 AND i.subject=$3 ORDER BY CASE t.kind WHEN 'personal' THEN 0 ELSE 1 END, CASE m.role WHEN 'owner' THEN 0 WHEN 'admin' THEN 1 ELSE 2 END,m.created_at,m.tenant_id LIMIT 1", ["text", "text", "text"]),
        ["identity.conversations"] = new("identity.conversations", "SELECT session_key,title,created_at,last_turn_at FROM app.conversation_sessions WHERE user_id=$1 AND tenant_id=$2 AND archived_at IS NULL ORDER BY last_turn_at DESC,session_key", ["uuid", "text"]),
        ["identity.create_account"] = new("identity.create_account", "WITH new_user AS (INSERT INTO app.users(user_id,display_name,email,avatar_url) VALUES($1,$9,$8,$10) RETURNING user_id), new_tenant AS (INSERT INTO app.tenants(tenant_id,display_name,kind) VALUES($3,$4,'personal') RETURNING tenant_id), new_identity AS (INSERT INTO app.external_identities(identity_id,user_id,provider,issuer,subject,email) SELECT $2,user_id,$5,$6,$7,$8 FROM new_user RETURNING user_id) INSERT INTO app.tenant_memberships(tenant_id,user_id,role) SELECT t.tenant_id,i.user_id,'owner' FROM new_tenant t CROSS JOIN new_identity i", ["uuid", "uuid", "text", "text", "text", "text", "text", "text", "text", "text"]),
        ["identity.put_session"] = new("identity.put_session", "INSERT INTO app.web_sessions(session_id,user_id,tenant_id,ticket,created_at,last_seen_at,expires_at,revoked_at) VALUES($1,$2,$3,$4,$5,$6,$7,NULL) ON CONFLICT(session_id) DO UPDATE SET ticket=EXCLUDED.ticket, last_seen_at=EXCLUDED.last_seen_at,expires_at=EXCLUDED.expires_at WHERE app.web_sessions.user_id=EXCLUDED.user_id AND app.web_sessions.tenant_id=EXCLUDED.tenant_id AND app.web_sessions.revoked_at IS NULL", ["text", "uuid", "text", "bytea", "timestamptz", "timestamptz", "timestamptz"]),
        ["identity.revoke_session"] = new("identity.revoke_session", "UPDATE app.web_sessions SET revoked_at=now() WHERE session_id=$1 AND user_id=$2 AND revoked_at IS NULL", ["text", "uuid"]),
        ["identity.revoke_workspace_sessions"] = new("identity.revoke_workspace_sessions", "UPDATE app.web_sessions SET revoked_at=now() WHERE tenant_id=$1 AND user_id=$2 AND revoked_at IS NULL", ["text", "uuid"]),
        ["identity.session"] = new("identity.session", "SELECT session_id,user_id,tenant_id,ticket,created_at,last_seen_at,expires_at,revoked_at FROM app.web_sessions WHERE session_id=$1 AND revoked_at IS NULL AND expires_at>now()", ["text"]),
        ["identity.sessions"] = new("identity.sessions", "SELECT session_id,user_id,tenant_id,ticket,created_at,last_seen_at,expires_at,revoked_at FROM app.web_sessions WHERE user_id=$1 AND revoked_at IS NULL AND expires_at>now() ORDER BY last_seen_at DESC,session_id", ["uuid"]),
        ["identity.update_profile"] = new("identity.update_profile", "WITH profile AS (UPDATE app.users SET display_name=COALESCE($6,display_name),email=COALESCE($5,email), avatar_url=COALESCE($7,avatar_url),updated_at=now() WHERE user_id=$1 RETURNING user_id) UPDATE app.external_identities SET email=COALESCE($5,email),last_login_at=now() WHERE provider=$2 AND issuer=$3 AND subject=$4 AND user_id IN(SELECT user_id FROM profile)", ["uuid", "text", "text", "text", "text", "text", "text"]),
        ["identity.upsert_client"] = new("identity.upsert_client", "INSERT INTO app.auth_clients(provider,client_id,authority,enabled,updated_at) VALUES($1,$2,$3,true,now()) ON CONFLICT(provider) DO UPDATE SET client_id=EXCLUDED.client_id,authority=EXCLUDED.authority,enabled=true,updated_at=now()", ["text", "text", "text"]),
        ["identity.upsert_conversation"] = new("identity.upsert_conversation", "INSERT INTO app.conversation_sessions(tenant_id,session_key,user_id,title,created_at,last_turn_at) VALUES($1,$2,$3,$4,now(),now()) ON CONFLICT(tenant_id,session_key) DO UPDATE SET last_turn_at=now(), title=COALESCE(app.conversation_sessions.title,EXCLUDED.title) WHERE app.conversation_sessions.user_id=EXCLUDED.user_id", ["text", "text", "uuid", "text"]),
        ["leaders.native_named"] = new("leaders.native_named", "WITH tops AS MATERIALIZED (SELECT c.claim, public.laplace_confidence(c.rating, c.deviation) AS confidence, coalesce(w.wcount, 0)::bigint AS witnesses FROM public.consensus c LEFT JOIN LATERAL (SELECT count(DISTINCT witness) AS wcount FROM public.attestation a WHERE a.claim = c.claim) w ON true WHERE c.matches > 0 ORDER BY confidence DESC, c.matches DESC, c.claim LIMIT $2) SELECT 0 AS band, 'consensus'::text AS band_name, encode(public.blake3_send(t.claim), 'hex'), coalesce((SELECT jsonb_agg(jsonb_build_object('id', encode(public.blake3_send(tc.child), 'hex'), 'label', coalesce(public.laplace_label_text(public.blake3_send(tc.child), true), encode(public.blake3_send(tc.child), 'hex'))) ORDER BY tc.ordinal)::text FROM public.laplace_constituents(ARRAY[t.claim]) tc), '[]'), t.confidence, t.witnesses, coalesce(public.laplace_text(public.blake3_send(t.claim)), '') AS trajectory FROM tops t", ["int4[]", "int4"]),
        ["migration.app_tables_present"] = new("migration.app_tables_present", "SELECT bool_and(to_regclass(name) IS NOT NULL) FROM unnest(ARRAY['app.users','app.external_identities','app.platform_roles','app.api_keys','app.billing_quotes','app.billing_royalties']) AS required(name)", []),
        ["migration.application_schema"] = new("migration.application_schema", "CREATE SCHEMA app", []),
        ["migration.application_schema_owner"] = new("migration.application_schema_owner", "CREATE SCHEMA app AUTHORIZATION {owner}", []),
        ["migration.canonical_substrate"] = new("migration.canonical_substrate", "CREATE EXTENSION IF NOT EXISTS laplace WITH SCHEMA public; ALTER EXTENSION laplace UPDATE; DO $canonical$ BEGIN IF NOT EXISTS (SELECT FROM pg_extension e JOIN pg_namespace n ON n.oid=e.extnamespace WHERE e.extname='laplace' AND n.nspname='public') THEN RAISE EXCEPTION 'The canonical laplace extension must own the public substrate'; END IF; IF NOT EXISTS (SELECT FROM pg_type t JOIN pg_depend d ON d.objid=t.oid AND d.classid='pg_type'::regclass JOIN pg_extension e ON e.oid=d.refobjid AND d.refclassid='pg_extension'::regclass WHERE t.oid=to_regtype('public.blake3') AND t.typlen=16 AND e.extname='laplace' AND d.deptype='e') OR to_regtype('public.blake3[]') IS NULL THEN RAISE EXCEPTION 'Canonical fixed-width blake3 identity type is not installed'; END IF; IF to_regclass('public.entity') IS NULL OR to_regclass('public.physicality') IS NULL OR to_regclass('public.attestation') IS NULL OR to_regclass('public.consensus') IS NULL THEN RAISE EXCEPTION 'Canonical 4-table substrate (entity, physicality, attestation, consensus) is missing'; END IF; PERFORM public.laplace_restore_function_bindings(); PERFORM public.laplace_ensure_stage(); END $canonical$;", []),
        ["migration.canonical_substrate_status"] = new("migration.canonical_substrate_status", "SELECT current_database(), extversion, public.laplace_fingerprint(), public.laplace_highway_fingerprint() FROM pg_extension WHERE extname='laplace'", []),
        ["migration.cutover_sessions"] = new("migration.cutover_sessions", "SELECT pg_terminate_backend(pid,5000) FROM pg_stat_activity WHERE datname=ANY($1) AND pid<>pg_backend_pid()", ["text[]"]),
        ["migration.database_access"] = new("migration.database_access", "SELECT 'GRANT '||a.privilege_type||' ON DATABASE ',\n       ' TO '||CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE quote_ident(pg_get_userbyid(a.grantee)) END\n       ||CASE WHEN a.is_grantable THEN ' WITH GRANT OPTION' ELSE '' END\nFROM pg_database d, LATERAL aclexplode(COALESCE(d.datacl,acldefault('d',d.datdba))) a\nWHERE d.datname=$1", ["text"]),
        ["migration.database_block"] = new("migration.database_block", "ALTER DATABASE {database} ALLOW_CONNECTIONS false", []),
        ["migration.database_create"] = new("migration.database_create", "CREATE DATABASE {database} {options}", []),
        ["migration.database_drop"] = new("migration.database_drop", "DROP DATABASE {database} WITH (FORCE)", []),
        ["migration.database_exists"] = new("migration.database_exists", "SELECT EXISTS (SELECT FROM pg_database WHERE datname=$1)", ["text"]),
        ["migration.database_options"] = new("migration.database_options", "SELECT format('OWNER %I TEMPLATE template0 ENCODING %L LOCALE_PROVIDER %s LC_COLLATE %L LC_CTYPE %L TABLESPACE %I CONNECTION LIMIT %s',\n    pg_get_userbyid(d.datdba), pg_encoding_to_char(d.encoding),\n    CASE d.datlocprovider WHEN 'i' THEN 'icu' WHEN 'b' THEN 'builtin' ELSE 'libc' END,\n    d.datcollate, d.datctype, t.spcname, d.datconnlimit)\n    || CASE WHEN d.datlocprovider='i' THEN format(' ICU_LOCALE %L',d.datlocale)\n            WHEN d.datlocprovider='b' THEN format(' BUILTIN_LOCALE %L',d.datlocale) ELSE '' END\n    || CASE WHEN d.daticurules IS NOT NULL THEN format(' ICU_RULES %L',d.daticurules) ELSE '' END\n    || CASE WHEN d.datcollversion IS NOT NULL THEN format(' COLLATION_VERSION %L',d.datcollversion) ELSE '' END\nFROM pg_database d JOIN pg_tablespace t ON t.oid=d.dattablespace\nWHERE d.datname=$1 AND NOT d.datistemplate AND d.datallowconn AND d.datconnlimit>=-1", ["text"]),
        ["migration.database_rename"] = new("migration.database_rename", "ALTER DATABASE {database} RENAME TO {replacement}", []),
        ["migration.database_reopen"] = new("migration.database_reopen", "ALTER DATABASE {database} ALLOW_CONNECTIONS true", []),
        ["migration.database_revoke_public"] = new("migration.database_revoke_public", "REVOKE ALL ON DATABASE {database} FROM PUBLIC", []),
        ["migration.database_settings"] = new("migration.database_settings", "SELECT CASE WHEN s.setrole=0 THEN 'ALTER DATABASE ' ELSE format('ALTER ROLE %I IN DATABASE ',pg_get_userbyid(s.setrole)) END,\n       format(' SET %I TO %L',split_part(v,'=',1),substr(v,strpos(v,'=')+1))\nFROM pg_db_role_setting s JOIN pg_database d ON d.oid=s.setdatabase,\n     LATERAL unnest(s.setconfig) v\nWHERE d.datname=$1 ORDER BY s.setrole,v", ["text"]),
        ["migration.declaration_present"] = new("migration.declaration_present", "SELECT to_regclass($1) IS NOT NULL", ["text"]),
        ["migration.declared_seed_snapshot"] = new("migration.declared_seed_snapshot", "SELECT 'tenant '||tenant_id,kind FROM app.tenants UNION ALL SELECT 'platform-role '||user_id::text,role FROM app.platform_roles ORDER BY 1,2", []),
        ["migration.declared_snapshot"] = new("migration.declared_snapshot", "WITH ns AS (SELECT oid,nspname FROM pg_namespace WHERE nspname !~ '^pg_' AND nspname<>'information_schema')\nSELECT key,value FROM (\nSELECT 'extension '||extname AS key,extversion AS value FROM pg_extension\nUNION ALL SELECT 'schema '||nspname,pg_get_userbyid(nspowner)||' '||coalesce(nspacl::text,'') FROM pg_namespace\n  WHERE nspname !~ '^pg_' AND nspname<>'information_schema'\nUNION ALL SELECT 'relation '||n.nspname||'.'||c.relname,\n  c.relkind::text||' '||pg_get_userbyid(c.relowner)||' '||coalesce(c.relacl::text,'')||' '||coalesce((SELECT md5(string_agg(\n    a.attname||':'||format_type(a.atttypid,a.atttypmod)||':'||a.attnotnull::text,',' ORDER BY a.attnum))\n    FROM pg_attribute a WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped),'')\n  FROM pg_class c JOIN ns n ON n.oid=c.relnamespace WHERE c.relkind IN ('r','p','v','m','f','S')\nUNION ALL SELECT 'index '||n.nspname||'.'||c.relname,pg_get_indexdef(c.oid)\n  FROM pg_class c JOIN ns n ON n.oid=c.relnamespace WHERE c.relkind IN ('i','I')\nUNION ALL SELECT 'trigger '||t.tgrelid::regclass::text||' '||t.tgname,pg_get_triggerdef(t.oid)\n  FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN ns n ON n.oid=c.relnamespace WHERE NOT t.tgisinternal\nUNION ALL SELECT 'constraint '||k.conrelid::regclass::text||' '||k.conname,pg_get_constraintdef(k.oid)\n  FROM pg_constraint k JOIN ns n ON n.oid=k.connamespace WHERE k.conrelid<>0\nUNION ALL SELECT 'function '||n.nspname||'.'||p.proname||'('||pg_get_function_identity_arguments(p.oid)||')',\n  md5(p.prosrc||coalesce(pg_get_function_sqlbody(p.oid),''))||' '||pg_get_userbyid(p.proowner)||' '||coalesce(p.proacl::text,'')\n  ||' '||coalesce(p.proconfig::text,'')\n  FROM pg_proc p JOIN ns n ON n.oid=p.pronamespace\nUNION ALL SELECT 'default-acl '||pg_get_userbyid(d.defaclrole)||' '||coalesce(d.defaclnamespace::regnamespace::text,'-')||' '||d.defaclobjtype::text,\n  d.defaclacl::text FROM pg_default_acl d\nUNION ALL SELECT 'membership '||m.roleid::regrole::text||' '||m.member::regrole::text,m.admin_option::text FROM pg_auth_members m\nUNION ALL SELECT 'database-acl',coalesce(datacl::text,'') FROM pg_database WHERE datname=current_database()\nUNION ALL SELECT 'database-setting '||CASE WHEN s.setrole=0 THEN '*' ELSE pg_get_userbyid(s.setrole) END||' '||split_part(v,'=',1),\n  substr(v,strpos(v,'=')+1)\n  FROM pg_db_role_setting s,LATERAL unnest(s.setconfig) v WHERE s.setdatabase=(SELECT oid FROM pg_database WHERE datname=current_database())\n) declared ORDER BY key,value", []),
        ["migration.object_access"] = new("migration.object_access", "WITH objects AS (\n    SELECT 'SCHEMA '||quote_ident(nspname) AS target,nspacl AS acl,nspowner AS owner\n    FROM pg_namespace WHERE nspname !~ '^pg_' AND nspname<>'information_schema'\n    UNION ALL\n    SELECT CASE WHEN c.relkind='S' THEN 'SEQUENCE ' ELSE 'TABLE ' END||format('%I.%I',n.nspname,c.relname),c.relacl,c.relowner\n    FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace\n    WHERE n.nspname !~ '^pg_' AND n.nspname<>'information_schema' AND c.relkind IN ('r','p','v','m','f','S')\n    UNION ALL\n    SELECT CASE WHEN p.prokind='p' THEN 'PROCEDURE ' ELSE 'FUNCTION ' END||format('%I.%I(%s)',n.nspname,p.proname,pg_get_function_identity_arguments(p.oid)),p.proacl,p.proowner\n    FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace\n    WHERE n.nspname !~ '^pg_' AND n.nspname<>'information_schema'\n    UNION ALL\n    SELECT 'TYPE '||format('%I.%I',n.nspname,t.typname),t.typacl,t.typowner\n    FROM pg_type t JOIN pg_namespace n ON n.oid=t.typnamespace\n    WHERE n.nspname !~ '^pg_' AND n.nspname<>'information_schema'\n)\n, defaults AS (\n    SELECT 'ALTER DEFAULT PRIVILEGES FOR ROLE '||quote_ident(pg_get_userbyid(d.defaclrole))\n        ||CASE WHEN n.oid IS NULL THEN '' ELSE ' IN SCHEMA '||quote_ident(n.nspname) END AS prefix,\n        CASE d.defaclobjtype WHEN 'r' THEN 'TABLES' WHEN 'S' THEN 'SEQUENCES' WHEN 'f' THEN 'FUNCTIONS'\n            WHEN 'T' THEN 'TYPES' WHEN 'n' THEN 'SCHEMAS' END AS kind,d.defaclacl AS acl,\n        CASE WHEN n.oid IS NULL THEN '' ELSE 'SCHEMA '||quote_ident(n.nspname) END AS target\n    FROM pg_default_acl d LEFT JOIN pg_namespace n ON n.oid=d.defaclnamespace\n), statements AS (\n    SELECT 0 AS ordinal,'REVOKE ALL ON '||target||' FROM PUBLIC' AS sql,target FROM objects WHERE acl IS NOT NULL\n    UNION ALL\n    SELECT 1,'GRANT '||a.privilege_type||' ON '||o.target||' TO '\n        ||CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE quote_ident(pg_get_userbyid(a.grantee)) END\n        ||CASE WHEN a.is_grantable THEN ' WITH GRANT OPTION' ELSE '' END,o.target\n    FROM objects o,LATERAL aclexplode(o.acl) a\n    UNION ALL\n    SELECT 2,prefix||' REVOKE ALL ON '||kind||' FROM PUBLIC',target FROM defaults\n    UNION ALL\n    SELECT 3,d.prefix||' GRANT '||a.privilege_type||' ON '||d.kind||' TO '\n        ||CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE quote_ident(pg_get_userbyid(a.grantee)) END\n        ||CASE WHEN a.is_grantable THEN ' WITH GRANT OPTION' ELSE '' END,d.target\n    FROM defaults d,LATERAL aclexplode(d.acl) a\n) SELECT sql,target FROM statements ORDER BY ordinal,sql", []),
